function processUserProfile(userObj) {
  return Object.assign(
    Object.fromEntries(
      Object.entries(userObj)
        .map(([key, value]) => [
          key,
          typeof value === 'string' ? value.toUpperCase() : value
        ])
    ),
    { lastModified: Date.now() }
  );
}

// Or as a more explicit chain:
function processUserProfileVerbose(userObj) {
  const transformedEntries = Object.entries(userObj)
    .map(([key, value]) => [
      key,
      typeof value === 'string' ? value.toUpperCase() : value
    ]);

  const transformedObj = Object.fromEntries(transformedEntries);
  return { ...transformedObj, lastModified: Date.now() };
}
```

This chained approach prevents mutation bugs because each transformation step creates new data structures rather than modifying existing ones. When you're building pipelines that pass data through multiple transformation functions, immutability ensures earlier steps aren't affected by later modifications. The functional composition also enables easier testing of individual transformation steps since they're pure functions without side effects.

However, your original `forEach()` approach remains clearer when you need complex side effects or multi-step mutations that don't fit cleanly into a map operation. For instance, if you needed to log each transformation, make external API calls during processing, or modify external state based on the values, the imperative approach with `forEach()` would be more appropriate.

