function transformUserProfile(rawUser: unknown): TargetUserProfile | null {
  // Single Type Guard to validate the shape of the raw record
  if (!isRawUserProfile(rawUser)) return null;

  const loginDate = new Date(rawUser.last_login_at);
  if (isNaN(loginDate.getTime())) return null;

  return {
    userId: rawUser.id,
    fullName: `${rawUser.first_name} ${rawUser.last_name}`,
    email: rawUser.email_address,
    accountStatus: statusMap[rawUser.status],
    lastLogin: loginDate,
