rivate static FeatureFlags CheckFeatureFlags(Configuration config)
{
    // Check configuration-based flags first
    var configFlags = CheckConfigFeatureFlags(config);

    // Apply environment variable overrides
    var envFlags = CheckEnvironmentFeatureFlags();

    // Merge with environment taking precedence
    return new FeatureFlags
    {
        NewFeature = envFlags.NewFeature ?? configFlags.NewFeature
    };
}

private static FeatureFlags CheckConfigFeatureFlags(Configuration config)
{
    var enableNewFeature = false;

    if (config.FeatureFlagData != null && config.FeatureFlagData.ContainsKey("newFeature"))
    {
        enableNewFeature = Convert.ToBoolean(config.FeatureFlagData["newFeature"]);
    }

    return new FeatureFlags
    {
        NewFeature = enableNewFeature
    };
}

private static FeatureFlags CheckEnvironmentFeatureFlags()
{
    bool? newFeature = null;
    if (Environment.GetEnvironmentVariable("FEATURE_NEW_FEATURE") != null)
    {
        newFeature = Convert.ToBoolean(Environment.GetEnvironmentVariable("FEATURE_NEW_FEATURE"));
    }

    return new FeatureFlags
    {
        NewFeature = newFeature
    };
}
```

This approach maintains the original behavior where environment variables override configuration values, but makes the precedence explicit and the logic more maintainable. Each method has a single responsibility: one for config flags, one for environment flags, and one for merging them with a clear precedence rule.

