export function createArrayData<T>(
  generator: (index: number) => T
): ArrayBenchData<T> {
  return {
    small: Array.from({ length: 100 }, (_, i) => generator(i)),
    medium: Array.from({ length: 1_000 }, (_, i) => generator(i)),
    large: Array.from({ length: 10_000 }, (_, i) => generator(i)),
