/** Assert benchmark meets performance threshold */
export function assertPerformance(
  result: BenchResult,
  minOpsPerSecond: number
): asserts result is BenchResult {
  if (result.hz < minOpsPerSecond) {
    throw new Error(
      `Performance threshold not met: ${result.hz.toFixed(0)} ops/s ` +
      `(required: ${minOpsPerSecond} ops/s)`
