terface UserProfile {
  id: number;
  userName: string;  // Standardized property name
  email: string;
  last_login_date: string;  // Keep original snake_case if that's your data source
  getPreferences?: () => UserPreferences;  // Optional method
}

interface UserPreferences {
  theme: string;
  notifications: boolean;
}

interface ProcessedProfile {
  id: number;
  name: string;
  emailVerified: string;
  lastLogin: string;
}

function processUserProfile(userObj: UserProfile): ProcessedProfile {
  const displayName = userObj.userName || 'Anonymous'; // Now guaranteed to exist with correct spelling
  const emailStatus = userObj.email ? 'verified' : 'unverified';

  if (userObj.getPreferences) {
    const prefs = userObj.getPreferences();
    console.log(`User ${displayName} has ${prefs.theme} theme`);
  }

  return {
    id: userObj.id,
    name: displayName,
    emailVerified: emailStatus,
    lastLogin: userObj.last_login_date
  };
}
```

Interfaces win here by preventing three specific runtime issues: 
1. Property typos like `username` vs `userName` are caught immediately at compile time rather than causing silent failures
2. Missing required properties like `email` trigger clear compiler errors instead of producing `undefined` values that crash later
3. Incorrect method calls like missing parentheses on `getPreferences()` are detected before execution

Your problematic call would now generate helpful compiler errors pointing exactly to the mismatched property names.

