function processUserProfile(userObj: UserProfile): ProcessedProfile {
  const displayName = userObj.userName || 'Anonymous'; // Now guaranteed to exist with correct spelling
  const emailStatus = userObj.email ? 'verified' : 'unverified';

  if (userObj.getPreferences) {
